/** The numeric value of a scalar row; a missing or ranged row is a programming error. */
export function row(id: string): number {
  const v = ROWS[id];
  if (typeof v !== "number") throw new Error(`knowledge row ${id} is not a scalar`);
  return v;
}

/** The [low, high] pair of a range row. */
export function rowRange(id: string): readonly [number, number] {
  const v = ROWS[id];
  if (typeof v === "number" || v === undefined) throw new Error(`knowledge row ${id} is not a range`);
  return v;
}
